import pandas as pd
from datetime import timedelta

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract the high_ts from watermark (single value)
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events with event_ts > high_ts
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # If no new events, return current snapshot
    if new_events.empty:
        return {"new_snapshot": target_snapshot[["user_id", "email", "status", "status_ts"]]}

    # Sort events by user_id, event_ts, event_seq for sequential processing
    new_events = new_events.sort_values(by=["user_id", "event_ts", "event_seq"]).reset_index(drop=True)

    # Create a working copy of the snapshot indexed by user_id
    snapshot_dict = {}
    for _, row in target_snapshot.iterrows():
        user_id = row["user_id"]
        snapshot_dict[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process each event sequentially
    for _, event in new_events.iterrows():
        event_seq = event["event_seq"]
        event_ts = event["event_ts"]
        op = event["op"]
        user_id = event["user_id"]
        email = event["email"]

        if user_id not in snapshot_dict:
            # New user
            current_state = None
        else:
            current_state = snapshot_dict[user_id]

        if op == "U":
            # Update operation
            if current_state is None:
                # New user: upsert with ACTIVE status
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
            elif current_state["status"] == "DELETED":
                # User is DELETED: check resurrection window (7 days = 168 hours)
                deletion_ts = current_state["status_ts"]
                # Resurrection only if event_ts > deletion_ts + 7 days (strict inequality)
                if event_ts > deletion_ts + timedelta(days=7):
                    # Resurrection allowed
                    snapshot_dict[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
                # else: discard the update, deletion is sticky
            else:
                # User is ACTIVE: upsert
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
        elif op == "D":
            # Delete operation: soft delete
            if current_state is None:
                # New user gets deleted immediately
                snapshot_dict[user_id] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": event_ts
                }
            else:
                # Mark existing user as DELETED, preserve email
                snapshot_dict[user_id] = {
                    "email": current_state["email"],
                    "status": "DELETED",
                    "status_ts": event_ts
                }

    # Convert snapshot_dict back to DataFrame
    result_rows = []
    for user_id, state in snapshot_dict.items():
        result_rows.append({
            "user_id": user_id,
            "email": state["email"],
            "status": state["status"],
            "status_ts": state["status_ts"]
        })

    new_snapshot = pd.DataFrame(result_rows)

    # Ensure correct data types
    if not new_snapshot.empty:
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = new_snapshot["status_ts"].astype("datetime64[us]")
    else:
        # Preserve schema for empty result
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = new_snapshot["status_ts"].astype("datetime64[us]")

    return {"new_snapshot": new_snapshot}
